def main():
    init_db()
    with get_session() as session:
        saumya = session.query(User).filter(User.username == "saumya").first()
        if not saumya:
            from database import _hash_password
            saumya = User(username="saumya", password_hash=_hash_password("123"), display_name="Saumya")
            session.add(saumya); session.commit(); session.refresh(saumya)
        print(f"User: {saumya.username} (id={saumya.id})")

        # Clear existing portfolio for fresh population
        existing = session.query(Portfolio).filter(Portfolio.user_id == saumya.id).delete()
        session.commit()
        print(f"Cleared {existing} existing holdings")

        added = 0
        for ticker, company, approx_price, sector in STOCKS:
            buy_price = round(approx_price * random.uniform(0.88, 1.08), 2)
            if buy_price > 10000: shares = random.randint(1, 20)
            elif buy_price > 1000: shares = random.randint(5, 100)
            elif buy_price > 100: shares = random.randint(20, 500)
            else: shares = random.randint(100, 2000)
            group = "holdings" if random.random() < 0.7 else "watchlist"
            session.add(Portfolio(user_id=saumya.id, ticker=ticker, company_name=company, shares=shares, buy_price=buy_price, group_name=group, notes=f"Mock holding. Sector: {sector}"))
            added += 1
        session.commit()
        print(f"Added {added} stocks")

        # Trade journal history
        holdings = session.query(Portfolio).filter(Portfolio.user_id == saumya.id, Portfolio.group_name == "holdings").limit(60).all()
        actions = ["BUY","SELL","HOLD","WATCH"]
        moods = ["Confident","Cautious","Neutral","Bullish","Bearish","Learning"]
        reasons = [
            "Strong quarterly results — revenue up 15% YoY",
            "Technical breakout above 200 DMA with high volume",
            "Promoter buying detected — insider confidence",
            "Sector rotation play — moving into defensives",
            "Valuation stretched after rally — booking partial profits",
            "Adding on dips — long-term conviction position",
            "Macro headwinds — reducing exposure temporarily",
            "New product launch catalyst — accumulating ahead of event",
            "Peer analysis shows undervaluation vs competitors",
            "Stop-loss triggered — disciplined exit",
        ]
        jc = 0
        for holding in holdings:
            for _ in range(random.randint(2,5)):
                days_ago = random.randint(1,365)
                price_at_time = round(holding.buy_price * random.uniform(0.85, 1.15), 2)
                session.add(TradeJournal(user_id=saumya.id, ticker=holding.ticker, action=random.choice(actions), price_at_time=price_at_time, reason_text=random.choice(reasons), outcome_text=f"Position {'gained' if random.random()>0.5 else 'lost'} {random.uniform(1,25):.1f}% since entry", company_name=holding.company_name, mood=random.choice(moods), created_at=datetime.utcnow() - timedelta(days=days_ago)))
                jc += 1
        session.commit()
        print(f"Added {jc} trade journal entries")

        total = session.query(Portfolio).filter(Portfolio.user_id == saumya.id).count()
        hc = session.query(Portfolio).filter(Portfolio.user_id == saumya.id, Portfolio.group_name == "holdings").count()
        wc = session.query(Portfolio).filter(Portfolio.user_id == saumya.id, Portfolio.group_name == "watchlist").count()
        jt = session.query(TradeJournal).filter(TradeJournal.user_id == saumya.id).count()
        print(f"\n=== Portfolio Summary ===")
        print(f"Total: {total} | Holdings: {hc} | Watchlist: {wc} | Journal entries: {jt}")

if __name__ == "__main__":
    main()
